    @Test void toolboxDefaultValuesCompileOnTheServer() throws Exception{
        // Generated by the editor from every toolbox block that comes with pre-filled number, text or true/false values.
        try(var in=ProgramsTest.class.getResourceAsStream("/toolbox-defaults-workspace.json")){
            var c=WorkspaceCompiler.compile(JsonParser.parseString(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject());
            for(var expected:List.of("turtle.select(1.0)","turtle.transferTo(2.0, 64.0)","turtle.drop(1.0)","turtleedu.setRedstone(true)","sleep(1.0)","1.0, 10.0","\"你好\""))assertTrue(c.lua().contains(expected),expected+" in\n"+c.lua());
        }
    }
    @Test void errorLinesFollowTheActualLuaChunkAndResetForANewRun(){
        var runtime=new ProgramRuntime();var compiled=new WorkspaceCompiler.Compiled("return 1",Map.of(3,"nested-block"),Set.of("nested-block"));
        runtime.prepare(compiled,false,"root-id","Root");runtime.errored("edu-program:3: bad call");assertEquals(3,runtime.json().get("errorLine").getAsInt());assertEquals("nested-block",runtime.json().get("blockId").getAsString());
        runtime.prepare(compiled,false,"root-id","Root");assertEquals(0,runtime.json().get("errorLine").getAsInt());
        runtime.library("child-id","孩子",new WorkspaceCompiler.Compiled("error('bad')",Map.of(),Set.of()));runtime.enterLibrary("孩子");runtime.errored("edu:孩子:1: bad");assertEquals("child-id",runtime.json().get("programId").getAsString());assertEquals(1,runtime.json().get("errorLine").getAsInt());
        runtime.errored("no source location");assertEquals(0,runtime.json().get("errorLine").getAsInt());
    }
    @TempDir Path dir;
    private static JsonObject json(String text){return JsonParser.parseString(text).getAsJsonObject();}
    @Test void nestedControlFlowTracksStableIdsAndEscapesText(){
        var ws=json("""
            {"blocks":{"blocks":[{"type":"controls_repeat_ext","id":"loop","inputs":{"TIMES":{"shadow":{"type":"math_number","id":"n","fields":{"NUM":2}}},"DO":{"block":{"type":"controls_if","id":"branch","inputs":{"IF0":{"block":{"type":"logic_boolean","id":"condition","fields":{"BOOL":"TRUE"}}},"DO0":{"block":{"type":"ccedu_turtle_command","id":"move","fields":{"COMMAND":"up"}}}}}}}}]}}
            """);
        var c=WorkspaceCompiler.compile(ws);assertTrue(c.lua().contains("for i"));assertTrue(c.lua().contains("if true then"));assertTrue(c.lua().contains("turtle.up()"));assertTrue(c.lines().containsValue("move"));assertEquals(Set.of("loop","n","branch","condition","move"),c.blockIds());
        assertEquals("\"a\\\"\\010\\092b\"",WorkspaceCompiler.quote("a\"\n\\b").replace("\\\\","\\092"));
    }
    @Test void everyTurtleActionCompilesButUnknownCodeAndDuplicateIdsAreRejected(){
        for(var command:WorkspaceCompiler.COMMANDS){var c=WorkspaceCompiler.compile(json("{\"blocks\":{\"blocks\":[{\"type\":\"ccedu_turtle_command\",\"id\":\"one\",\"fields\":{\"COMMAND\":\""+command+"\"}}]}}"));assertTrue(c.lua().contains("turtle."+command+"()"));}
        assertThrows(WorkspaceCompiler.Invalid.class,()->WorkspaceCompiler.compile(json("{\"blocks\":{\"blocks\":[{\"type\":\"ccedu_turtle_command\",\"id\":\"one\",\"fields\":{\"COMMAND\":\"forward();os.shutdown\"}}]}}")));
        assertThrows(WorkspaceCompiler.Invalid.class,()->WorkspaceCompiler.compile(json("{\"blocks\":{\"blocks\":[{\"type\":\"text\",\"id\":\"same\",\"fields\":{\"TEXT\":\"a\"}},{\"type\":\"text\",\"id\":\"same\",\"fields\":{\"TEXT\":\"b\"}}]}}")));
        assertThrows(WorkspaceCompiler.Invalid.class,()->WorkspaceCompiler.compile(json("{\"blocks\":{\"blocks\":[{\"type\":\"arbitrary_lua\",\"id\":\"code\"}]}}")));
    }
    @Test void eachActionBlockCompilesOnlyItsOwnCommands(){
        String one="{\"blocks\":{\"blocks\":[{\"type\":\"%s\",\"id\":\"one\",\"fields\":{\"COMMAND\":\"%s\"}}]}}";
        var covered=new HashSet<String>();
        for(var entry:WorkspaceCompiler.ACTION_BLOCKS.entrySet())for(var command:entry.getValue()){
            assertTrue(WorkspaceCompiler.COMMANDS.contains(command),command);covered.add(command);
            assertTrue(WorkspaceCompiler.compile(json(one.formatted(entry.getKey(),command))).lua().contains("turtle."+command+"()"),entry.getKey()+" "+command);
        }
        assertEquals(WorkspaceCompiler.COMMANDS,covered,"every turtle command has an action block");
        // A dig block cannot be edited into a move, and the drop block takes no amount.
        assertEquals("Unknown turtle command",assertThrows(WorkspaceCompiler.Invalid.class,()->WorkspaceCompiler.compile(json(one.formatted("ccedu_dig","forward")))).getMessage());
        assertEquals("Unknown turtle command",assertThrows(WorkspaceCompiler.Invalid.class,()->WorkspaceCompiler.compile(json(one.formatted("ccedu_move","detect")))).getMessage());
        assertTrue(WorkspaceCompiler.compile(json(one.formatted("ccedu_drop","drop")),false).lua().contains("turtle.drop()\n"));
    }
    @Test void repeatedSavesUseCachedRowsButNoticeFilesChangedElsewhere()throws Exception{
        var turtle=UUID.randomUUID();var id=UUID.randomUUID();var store=new ProgramStore(dir);var p=json("{\"name\":\"快存\",\"mode\":\"lua\",\"source\":\"turtle.up()\"}");
        for(int revision=0;revision<5;revision++)assertEquals(revision+1,store.save(turtle,id,revision,p).get("revision").getAsInt());
        var row=store.list(turtle).get(0).getAsJsonObject();assertEquals(5,row.get("revision").getAsInt());assertEquals("快存",row.get("name").getAsString());
        // A restored backup replaces the file behind the cache; its revision, not the cached one, decides conflicts.
        var file=dir.resolve(turtle.toString()).resolve(id+".json");var restored=json(Files.readString(file));restored.addProperty("revision",9);restored.addProperty("name","備份");var before=Files.getLastModifiedTime(file);Files.writeString(file,restored.toString());
        // Same length and inode as the cached file; a real restore lands seconds later, which coarse CI file clocks need to see.
        Files.setLastModifiedTime(file,java.nio.file.attribute.FileTime.fromMillis(before.toMillis()+2000));
        assertThrows(IllegalStateException.class,()->store.save(turtle,id,5,p));
        assertEquals("備份",store.list(turtle).get(0).getAsJsonObject().get("name").getAsString());
        p.addProperty("name","新名字");assertEquals(10,store.save(turtle,id,9,p).get("revision").getAsInt());
        assertEquals("新名字",new ProgramStore(dir).list(turtle).get(0).getAsJsonObject().get("name").getAsString());
    }
    @Test void separateLuaAndBlocksSurviveReloadWithConflictsAndRecoverableDelete()throws Exception{
        var turtle=UUID.randomUUID();var id=UUID.randomUUID();var store=new ProgramStore(dir);var p=json("{\"name\":\"中文程式\",\"mode\":\"lua\",\"source\":\"turtle.up()\"}");
        store.save(turtle,id,0,p);assertEquals("turtle.up()",new ProgramStore(dir).load(turtle,id).get("source").getAsString());
        assertThrows(IllegalStateException.class,()->store.save(turtle,id,0,p));
        p.addProperty("name","renamed");store.save(turtle,id,1,p);assertEquals(2,store.named(turtle,"renamed").get("revision").getAsInt());
        assertThrows(IllegalStateException.class,()->store.delete(turtle,id,1));store.delete(turtle,id,2);assertEquals(0,store.list(turtle).size());
        try(var files=Files.walk(dir)){assertTrue(files.anyMatch(f->f.toString().endsWith(".deleted")));}
    }
