    @Test void failedDependencyPublicationRollsBackWithoutChangingExistingPrograms()throws Exception{
        var turtle=UUID.randomUUID();var store=new ProgramStore(dir);var oldId=UUID.randomUUID();var old=json("{\"name\":\"existing\",\"mode\":\"lua\",\"source\":\"return 1\"}");var saved=store.save(turtle,oldId,0,old);
        var helper=json("{\"name\":\"helper\",\"mode\":\"lua\",\"source\":\"return 2\"}");var root=json("{\"name\":\"main\",\"mode\":\"lua\",\"source\":\"edu.runProgram('helper')\"}");var count=new int[]{0};
        var failing=new ProgramStore(dir,(from,to)->{if(++count[0]==2)throw new java.io.IOException("Simulated full disk during root publication");Files.move(from,to,StandardCopyOption.ATOMIC_MOVE);});
        assertThrows(java.io.IOException.class,()->failing.createBatch(turtle,List.of(helper,root)));
        assertEquals(1,store.list(turtle).size());assertEquals(saved,store.load(turtle,oldId));assertFalse(Files.exists(dir.resolve(turtle.toString()).resolve(".import-pending")));
        assertEquals(2,store.createBatch(turtle,List.of(helper,root)).size());assertEquals(3,store.list(turtle).size());
    }
